#!/bin/sh
set -eu

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
version=$(sed -n 's/^Version:[[:space:]]*//p' "$root/packaging/fedora-store.spec")
topdir=${RPM_TOPDIR:-"$root/.rpmbuild"}
source="$topdir/SOURCES/fedora-store-$version.tar.gz"

rm -rf "$topdir"
mkdir -p "$topdir"/{BUILD,BUILDROOT,RPMS,SOURCES,SPECS,SRPMS}

# Keep the source archive free of local build state and generated bytecode.
tar -czf "$source" \
  --exclude='./.git' \
  --exclude='./.direnv' \
  --exclude='./.rpmbuild' \
  --exclude='./__pycache__' \
  --exclude='*/__pycache__' \
  --transform="s,^\\./,fedora-store-$version/," \
  -C "$root" .

cp "$root/packaging/fedora-store.spec" "$topdir/SPECS/"
rpmbuild -ba \
  --define "_topdir $topdir" \
  --define "_prefix /usr" \
  "$topdir/SPECS/fedora-store.spec"

printf '\nRPM output:\n'
find "$topdir/RPMS" -type f -name '*.rpm' -print
